export const STYLE_CSS = ":root,\n:root[data-theme=\"light\"] {\n  /* Light Theme — Framed Sheet Studio Palette (Default) */\n  --ground: #f3f5f8;\n  --surface: #ffffff;\n  --raised: #f7f9fb;\n  --well: #f1f4f8;\n  --active: #e6eaf0;\n\n  --border: #e3e7ee;\n  --rule: #edf0f5;\n  --control: #cbd2dc;\n  --control-hover: #94a3b8;\n\n  --text: #0f172a;\n  --muted: #475569;\n  --faint: #475569;\n\n  --primary-bg: #0f172a;\n  --primary-ink: #ffffff;\n  --secondary-bg: #f1f5f9;\n  --secondary-ink: #0f172a;\n\n  --accent: #0f766e;\n  --pill-positive-bg: #dcfce7;\n  --pill-positive-ink: #065f46;\n  --pill-negative-bg: #fee2e2;\n  --pill-negative-ink: #991b1b;\n  --pill-neutral-bg: #edf1f7;\n  --pill-neutral-ink: #334155;\n\n  --radius-sheet: 16px;\n  --radius-card: 14px;\n  --radius-control: 10px;\n  --radius-pill: 999px;\n\n  --font-sans: \"Plus Jakarta Sans\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n\n  --fs-hero: 28px;\n  --fs-section: 16px;\n  --fs-body: 14px;\n  --fs-small: 12px;\n\n  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);\n}\n\n:root[data-theme=\"dark\"] {\n  /* Dark Theme — Precision Obsidian Studio Palette */\n  --ground: #08090c;\n  --surface: #111318;\n  --raised: #171a21;\n  --well: #0b0d11;\n  --active: #232730;\n\n  --border: #222630;\n  --rule: #1b1f27;\n  --control: #333947;\n  --control-hover: #64748b;\n\n  --text: #f8fafc;\n  --muted: #94a3b8;\n  --faint: #64748b;\n\n  --primary-bg: #ffffff;\n  --primary-ink: #090b0e;\n  --secondary-bg: #1e222b;\n  --secondary-ink: #f8fafc;\n\n  --accent: #2dd4bf;\n  --pill-positive-bg: #0f2922;\n  --pill-positive-ink: #34d399;\n  --pill-negative-bg: #2c1518;\n  --pill-negative-ink: #f87171;\n  --pill-neutral-bg: #1e222b;\n  --pill-neutral-ink: #cbd5e1;\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  width: 100%;\n  max-width: 100%;\n  overflow-x: hidden;\n  background-color: var(--ground);\n  color: var(--text);\n  font-family: var(--font-sans);\n  font-size: var(--fs-body);\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  transition: background-color 180ms ease, color 180ms ease;\n}\n\n.num {\n  font-variant-numeric: tabular-nums;\n}\n\n/* 1. Outer Tinted Frame & Inset Workspace Sheet */\n.app-frame {\n  padding: 16px 12px 28px;\n  display: flex;\n  flex-direction: column;\n}\n\n.workspace-sheet {\n  width: 100%;\n  max-width: 980px;\n  margin: 0 auto;\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sheet);\n  display: flex;\n  flex-direction: column;\n  transition: background-color 180ms ease, border-color 180ms ease;\n}\n\n/* 2. Top Header Bar */\n.top-header {\n  height: 64px;\n  padding: 0 28px;\n  border-bottom: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.brand-group {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-shrink: 0;\n  min-width: 0;\n}\n\n.brand-badge {\n  width: 32px;\n  height: 32px;\n  border-radius: 8px;\n  background-color: var(--primary-bg);\n  color: var(--primary-ink);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: var(--fs-small);\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  flex-shrink: 0;\n}\n\n.brand-title {\n  font-size: 16px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  color: var(--text);\n  white-space: nowrap;\n}\n\n.header-controls {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-shrink: 0;\n}\n\n/* Segmented Theme Switcher */\n.theme-switcher {\n  display: inline-flex;\n  align-items: center;\n  padding: 3px;\n  background-color: var(--well);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-control);\n  gap: 2px;\n}\n\n.theme-btn {\n  height: 30px;\n  padding: 0 10px;\n  background: transparent;\n  border: none;\n  border-radius: 7px;\n  color: var(--muted);\n  font-family: var(--font-sans);\n  font-size: var(--fs-small);\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  cursor: pointer;\n  line-height: 1;\n  transition: transform 150ms var(--ease-out), background-color 150ms ease, color 150ms ease;\n}\n\n.theme-btn.active {\n  background-color: var(--surface);\n  color: var(--text);\n  border: 1px solid var(--border);\n}\n\n.theme-btn:active {\n  transform: scale(0.97);\n}\n\n.theme-icon {\n  width: 14px;\n  height: 14px;\n  flex-shrink: 0;\n}\n\n.btn-telegram-nav {\n  height: 36px;\n  padding: 0 14px;\n  background-color: var(--secondary-bg);\n  border: 1px solid var(--control);\n  border-radius: var(--radius-control);\n  color: var(--secondary-ink);\n  font-size: var(--fs-body);\n  font-weight: 600;\n  text-decoration: none;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  white-space: nowrap;\n  line-height: 1;\n  transition: transform 150ms var(--ease-out), border-color 150ms ease, background-color 150ms ease;\n}\n\n.btn-telegram-nav:active {\n  transform: scale(0.97);\n}\n\n.icon-xs {\n  width: 13px;\n  height: 13px;\n  flex-shrink: 0;\n}\n\n.icon-sm {\n  width: 15px;\n  height: 15px;\n  flex-shrink: 0;\n}\n\n.icon-md {\n  width: 18px;\n  height: 18px;\n  flex-shrink: 0;\n}\n\n/* 3. Main Workspace Content */\n.main-content {\n  padding: 32px 28px 40px;\n  display: flex;\n  flex-direction: column;\n  gap: 28px;\n}\n\n/* 4. Minimal Hero & Focused Download Box */\n.hero-section {\n  width: 100%;\n  max-width: 640px;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  text-align: center;\n}\n\n.hero-header {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n}\n\n.hero-title {\n  font-size: var(--fs-hero);\n  font-weight: 700;\n  letter-spacing: -0.03em;\n  color: var(--text);\n  line-height: 1.2;\n}\n\n.hero-subtitle {\n  font-size: 15px;\n  font-weight: 500;\n  color: var(--muted);\n}\n\n/* Modern Unified Composer Card */\n.composer-card {\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  transition: border-color 150ms ease, box-shadow 150ms ease;\n}\n\n.composer-card:focus-within {\n  border-color: var(--control-hover);\n}\n\n/* Input Well */\n.input-well {\n  display: flex;\n  align-items: center;\n  background-color: var(--well);\n  border: 1px solid var(--control);\n  border-radius: var(--radius-control);\n  height: 48px;\n  padding: 0 8px 0 14px;\n  gap: 10px;\n  transition: border-color 150ms ease, background-color 150ms ease;\n}\n\n.input-well:focus-within {\n  border-color: var(--text);\n  background-color: var(--surface);\n}\n\n.input-icon {\n  width: 18px;\n  height: 18px;\n  color: var(--muted);\n  flex-shrink: 0;\n}\n\n.composer-input {\n  flex: 1;\n  min-width: 0;\n  height: 100%;\n  background: transparent;\n  border: none;\n  color: var(--text);\n  font-family: var(--font-sans);\n  font-size: 15px;\n  font-weight: 500;\n  outline: none;\n  text-overflow: ellipsis;\n}\n\n.composer-input::placeholder {\n  color: var(--faint);\n  font-weight: 400;\n}\n\n.input-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-shrink: 0;\n}\n\n.btn-input-paste {\n  height: 32px;\n  padding: 0 12px;\n  background-color: var(--surface);\n  border: 1px solid var(--control);\n  border-radius: 8px;\n  color: var(--text);\n  font-family: var(--font-sans);\n  font-size: var(--fs-small);\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  cursor: pointer;\n  line-height: 1;\n  transition: transform 150ms var(--ease-out), border-color 150ms ease;\n}\n\n.btn-input-paste:active {\n  transform: scale(0.97);\n}\n\n.btn-input-clear {\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  background-color: var(--raised);\n  border: 1px solid var(--border);\n  color: var(--muted);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  line-height: 1;\n  padding: 0;\n  transition: transform 150ms var(--ease-out), color 150ms ease, border-color 150ms ease;\n}\n\n.btn-input-clear svg {\n  width: 14px;\n  height: 14px;\n}\n\n.btn-input-clear:active {\n  transform: scale(0.94);\n}\n\n/* Action Row */\n.composer-action-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.btn-sample-hint {\n  height: 34px;\n  padding: 0 12px;\n  background-color: var(--well);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-pill);\n  color: var(--muted);\n  font-family: var(--font-sans);\n  font-size: var(--fs-small);\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  cursor: pointer;\n  line-height: 1;\n  transition: transform 150ms var(--ease-out), border-color 150ms ease, color 150ms ease;\n}\n\n.btn-sample-hint:active {\n  transform: scale(0.97);\n}\n\n.btn-primary-submit {\n  height: 42px;\n  padding: 0 24px;\n  background-color: var(--primary-bg);\n  color: var(--primary-ink);\n  border: none;\n  border-radius: var(--radius-control);\n  font-family: var(--font-sans);\n  font-size: 15px;\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  cursor: pointer;\n  white-space: nowrap;\n  line-height: 1;\n  transition: transform 150ms var(--ease-out), opacity 150ms ease;\n}\n\n.btn-primary-submit:active {\n  transform: scale(0.97);\n}\n\n.btn-primary-submit:disabled {\n  opacity: 0.65;\n  cursor: default;\n}\n\n/* Error Notice */\n.error-banner {\n  background-color: var(--pill-negative-bg);\n  color: var(--pill-negative-ink);\n  border-radius: var(--radius-control);\n  padding: 12px 16px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  font-size: var(--fs-body);\n  font-weight: 500;\n  text-align: left;\n}\n\n.btn-error-dismiss {\n  background: transparent;\n  border: none;\n  color: inherit;\n  font-family: var(--font-sans);\n  font-size: var(--fs-body);\n  font-weight: 700;\n  text-decoration: underline;\n  cursor: pointer;\n}\n\n/* 5. Dynamic Resolved Media Inspector Card */\n.resolved-card {\n  background-color: var(--raised);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  padding: 22px;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.resolved-header {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding-bottom: 14px;\n  border-bottom: 1px solid var(--border);\n}\n\n.resolved-head-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.resolved-badges {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n@media (min-width: 641px) {\n  .resolved-header {\n    flex-direction: row;\n    align-items: center;\n    justify-content: space-between;\n  }\n}\n\n.section-heading {\n  font-size: var(--fs-section);\n  font-weight: 700;\n  letter-spacing: -0.01em;\n  color: var(--text);\n}\n\n.badge-success {\n  height: 26px;\n  padding: 0 10px;\n  background-color: var(--pill-positive-bg);\n  color: var(--pill-positive-ink);\n  border-radius: var(--radius-pill);\n  font-size: var(--fs-small);\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  white-space: nowrap;\n}\n\n.spec-chip {\n  height: 26px;\n  padding: 0 10px;\n  background-color: var(--pill-neutral-bg);\n  color: var(--pill-neutral-ink);\n  border: 1px solid var(--border);\n  border-radius: 7px;\n  font-size: var(--fs-small);\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  white-space: nowrap;\n}\n\n.btn-reset-inspector {\n  height: 32px;\n  padding: 0 12px;\n  background-color: var(--surface);\n  border: 1px solid var(--control);\n  border-radius: 8px;\n  color: var(--text);\n  font-family: var(--font-sans);\n  font-size: var(--fs-small);\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  cursor: pointer;\n  line-height: 1;\n  flex-shrink: 0;\n  transition: transform 150ms var(--ease-out), border-color 150ms ease;\n}\n\n.btn-reset-inspector:active {\n  transform: scale(0.97);\n}\n\n.resolved-grid {\n  display: grid;\n  grid-template-columns: 220px minmax(0, 1fr);\n  gap: 22px;\n  align-items: stretch;\n}\n\n.preview-column {\n  display: flex;\n  flex-direction: column;\n}\n\n.video-frame {\n  position: relative;\n  width: 100%;\n  height: 100%;\n  min-height: 340px;\n  background-color: #090a0f;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  overflow: hidden;\n  cursor: pointer;\n}\n\n.video-frame video {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n\n.video-top-overlay {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  right: 10px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  z-index: 2;\n}\n\n.video-tag {\n  background-color: #111318;\n  color: #ffffff;\n  padding: 4px 9px;\n  border-radius: 6px;\n  font-size: var(--fs-small);\n  font-weight: 600;\n}\n\n.video-mute-btn {\n  width: 32px;\n  height: 32px;\n  border-radius: 50%;\n  background-color: #111318;\n  border: 1px solid #333947;\n  color: #ffffff;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n}\n\n.video-mute-btn svg {\n  width: 15px;\n  height: 15px;\n}\n\n.play-overlay {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: opacity 150ms ease;\n}\n\n.play-overlay.playing {\n  opacity: 0;\n  pointer-events: none;\n}\n\n.play-button-circle {\n  width: 48px;\n  height: 48px;\n  border-radius: 50%;\n  background-color: #111318;\n  border: 1px solid #475569;\n  color: #ffffff;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  transition: transform 150ms var(--ease-out);\n}\n\n.play-button-circle svg {\n  width: 18px;\n  height: 18px;\n}\n\n.video-bottom-bar {\n  position: absolute;\n  left: 10px;\n  right: 10px;\n  bottom: 10px;\n  background-color: #111318;\n  border-radius: 8px;\n  padding: 7px 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  z-index: 2;\n}\n\n.timecode-label {\n  font-size: var(--fs-small);\n  font-weight: 600;\n  color: #ffffff;\n}\n\n.progress-rail {\n  width: 100%;\n  height: 4px;\n  background-color: #334155;\n  border-radius: var(--radius-pill);\n  overflow: hidden;\n}\n\n.progress-fill {\n  width: 0%;\n  height: 100%;\n  background-color: #34d399;\n}\n\n/* Action & Metadata Right Column */\n.action-column {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  gap: 18px;\n  min-width: 0;\n}\n\n.creator-card {\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  padding: 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.creator-profile {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n}\n\n.creator-avatar {\n  width: 44px;\n  height: 44px;\n  border-radius: 50%;\n  object-fit: cover;\n  background-color: var(--well);\n  border: 1px solid var(--border);\n  flex-shrink: 0;\n}\n\n.creator-names {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  flex: 1;\n}\n\n.creator-name {\n  font-size: 16px;\n  font-weight: 700;\n  color: var(--text);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.creator-handle {\n  font-size: var(--fs-body);\n  color: var(--muted);\n}\n\n.media-caption {\n  font-size: var(--fs-body);\n  color: var(--text);\n  line-height: 1.5;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n\n.sound-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  background-color: var(--well);\n  border-radius: 8px;\n  color: var(--muted);\n  font-size: var(--fs-body);\n  font-weight: 500;\n}\n\n.sound-title {\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* Photo Carousel Grid */\n.photo-carousel-block {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.photo-carousel-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-weight: 600;\n}\n\n.photo-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.photo-slide {\n  border-radius: 8px;\n  overflow: hidden;\n  border: 1px solid var(--border);\n  aspect-ratio: 3 / 4;\n  display: block;\n}\n\n.photo-slide img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n\n/* Download Buttons Stack (Generous Spacing & Tactile Hierarchy) */\n.download-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.btn-download-primary,\n.btn-download-secondary {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  min-height: 56px;\n  padding: 12px 18px;\n  border-radius: var(--radius-card);\n  text-decoration: none;\n  cursor: pointer;\n  line-height: 1.3;\n  transition: transform 150ms var(--ease-out), opacity 150ms ease, background-color 150ms ease;\n}\n\n.btn-download-primary {\n  background-color: var(--primary-bg);\n  color: var(--primary-ink);\n}\n\n.btn-download-secondary {\n  background-color: var(--surface);\n  color: var(--text);\n  border: 1px solid var(--control);\n}\n\n.btn-download-primary:active,\n.btn-download-secondary:active {\n  transform: scale(0.98);\n}\n\n.dl-btn-copy {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n\n.dl-btn-title {\n  font-size: 15px;\n  font-weight: 700;\n}\n\n.dl-btn-sub {\n  font-size: var(--fs-small);\n  opacity: 0.8;\n}\n\n.utility-button-row {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.btn-utility {\n  height: 38px;\n  padding: 0 12px;\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-control);\n  color: var(--muted);\n  font-family: var(--font-sans);\n  font-size: var(--fs-body);\n  font-weight: 600;\n  text-decoration: none;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  white-space: nowrap;\n  line-height: 1;\n  transition: transform 150ms var(--ease-out), border-color 150ms ease, color 150ms ease;\n}\n\n.btn-utility:active {\n  transform: scale(0.97);\n}\n\n/* Divided Stats Strip */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n}\n\n.stat-item {\n  padding: 12px 14px;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  border-right: 1px solid var(--border);\n}\n\n.stat-item:last-child {\n  border-right: none;\n}\n\n.stat-label {\n  font-size: var(--fs-small);\n  color: var(--muted);\n  font-weight: 500;\n}\n\n.stat-number {\n  font-size: 18px;\n  font-weight: 700;\n  color: var(--text);\n}\n\n/* 6. Recent Downloads Section */\n.recent-section {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.section-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.section-note {\n  font-size: var(--fs-small);\n  font-weight: 600;\n  color: var(--muted);\n}\n\n.btn-text-quiet {\n  background: transparent;\n  border: none;\n  color: var(--muted);\n  font-family: var(--font-sans);\n  font-size: var(--fs-body);\n  font-weight: 600;\n  cursor: pointer;\n}\n\n/* Recent History Grid */\n.recent-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.recent-item {\n  background-color: var(--raised);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  padding: 12px;\n  display: grid;\n  grid-template-columns: 48px minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 12px;\n}\n\n.recent-thumb {\n  width: 48px;\n  height: 48px;\n  border-radius: 8px;\n  object-fit: cover;\n  background-color: var(--well);\n}\n\n.recent-info {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n\n.recent-title {\n  font-size: var(--fs-body);\n  font-weight: 600;\n  color: var(--text);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.recent-sub {\n  font-size: var(--fs-small);\n  color: var(--muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.btn-recent-load {\n  height: 32px;\n  padding: 0 12px;\n  background-color: var(--surface);\n  border: 1px solid var(--control);\n  border-radius: 8px;\n  color: var(--text);\n  font-family: var(--font-sans);\n  font-size: var(--fs-small);\n  font-weight: 600;\n  cursor: pointer;\n  line-height: 1;\n}\n\n/* 7. Clean FAQ Section (Below The Fold) */\n.faq-section {\n  margin-top: 18px;\n  padding-top: 24px;\n  border-top: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.faq-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.faq-item {\n  background-color: var(--raised);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  padding: 18px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.faq-question {\n  font-size: 14px;\n  font-weight: 700;\n  color: var(--text);\n  line-height: 1.35;\n}\n\n.faq-answer {\n  font-size: 13px;\n  color: var(--muted);\n  line-height: 1.55;\n}\n\n.faq-link {\n  color: var(--text);\n  font-weight: 600;\n  text-decoration: underline;\n}\n\n/* Minimal Studio Footer */\n.studio-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 14px 18px;\n  background-color: var(--well);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-card);\n  flex-wrap: wrap;\n  margin-top: 6px;\n}\n\n.footer-supported {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.footer-label {\n  font-size: var(--fs-small);\n  font-weight: 600;\n  color: var(--muted);\n}\n\n.url-pattern {\n  padding: 3px 8px;\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 5px;\n  font-size: 11px;\n  font-weight: 500;\n  color: var(--muted);\n}\n\n.footer-credit {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.credit-link {\n  color: var(--muted);\n  text-decoration: none;\n  transition: color 150ms ease;\n}\n\n.credit-dot {\n  color: var(--control);\n}\n\n/* Pointer Hover Enhancements */\n@media (hover: hover) and (pointer: fine) {\n  .btn-telegram-nav:hover,\n  .btn-input-paste:hover,\n  .btn-sample-hint:hover,\n  .btn-reset-inspector:hover,\n  .btn-download-secondary:hover,\n  .btn-utility:hover,\n  .btn-recent-load:hover {\n    border-color: var(--control-hover);\n    color: var(--text);\n  }\n  .btn-primary-submit:hover,\n  .btn-download-primary:hover {\n    opacity: 0.92;\n  }\n  .credit-link:hover,\n  .btn-text-quiet:hover {\n    color: var(--text);\n  }\n}\n\n/* Responsive Breakpoints */\n@media (max-width: 840px) {\n  .faq-grid {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .recent-grid {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .resolved-grid {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .video-frame {\n    min-height: 240px;\n    max-height: 300px;\n  }\n}\n\n@media (max-width: 640px) {\n  .app-frame {\n    padding: 0;\n  }\n  .workspace-sheet {\n    border: none;\n    border-radius: 0;\n  }\n  .top-header {\n    height: 56px;\n    padding: 0 18px;\n    gap: 8px;\n  }\n  .brand-group {\n    gap: 8px;\n  }\n  .brand-title {\n    font-size: 15px;\n  }\n  .theme-label {\n    display: none;\n  }\n  .theme-btn {\n    padding: 0 8px;\n    height: 28px;\n  }\n  .btn-telegram-nav {\n    height: 32px;\n    padding: 0 10px;\n    font-size: var(--fs-small);\n  }\n  .main-content {\n    padding: 24px 18px 32px;\n    gap: 24px;\n  }\n  .hero-section {\n    text-align: left;\n    gap: 14px;\n  }\n  .hero-header {\n    align-items: flex-start;\n  }\n  .hero-title {\n    font-size: 24px;\n  }\n  .composer-card {\n    padding: 12px;\n    gap: 10px;\n  }\n  .input-well {\n    height: 44px;\n    padding: 0 6px 0 12px;\n  }\n  .composer-action-row {\n    flex-direction: column;\n    align-items: stretch;\n    gap: 8px;\n  }\n  .btn-primary-submit {\n    width: 100%;\n    height: 44px;\n    font-size: 15px;\n  }\n  .btn-sample-hint {\n    width: 100%;\n    height: 32px;\n    justify-content: center;\n  }\n  .resolved-card {\n    padding: 14px;\n    gap: 14px;\n  }\n  .resolved-grid {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 16px;\n  }\n  .video-frame {\n    min-height: 200px;\n    max-height: 220px;\n  }\n  .utility-button-row {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .stats-strip {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n  .stat-item:nth-child(2) {\n    border-right: none;\n  }\n  .stat-item:nth-child(1),\n  .stat-item:nth-child(2) {\n    border-bottom: 1px solid var(--border);\n  }\n  .studio-footer {\n    flex-direction: column;\n    align-items: flex-start;\n    gap: 12px;\n  }\n}\n\n@media (max-width: 400px) {\n  .nav-label {\n    display: none;\n  }\n  .btn-telegram-nav {\n    padding: 0 8px;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    transition-duration: 0.01ms !important;\n    animation-duration: 0.01ms !important;\n  }\n}\n";
export const APP_JS = "document.addEventListener('DOMContentLoaded', () => {\n  const htmlRoot = document.documentElement;\n  const themeLightBtn = document.getElementById('themeLightBtn');\n  const themeDarkBtn = document.getElementById('themeDarkBtn');\n\n  const extractForm = document.getElementById('extractForm');\n  const dockUrl = document.getElementById('dockUrl');\n  const clearInputBtn = document.getElementById('clearInputBtn');\n  const pasteBtn = document.getElementById('pasteBtn');\n  const pasteBtnLabel = document.getElementById('pasteBtnLabel');\n  const sampleBtn = document.getElementById('sampleBtn');\n  const extractBtn = document.getElementById('extractBtn');\n\n  const errorBanner = document.getElementById('errorBanner');\n  const errorText = document.getElementById('errorText');\n  const dismissErrorBtn = document.getElementById('dismissErrorBtn');\n\n  const inspectorCard = document.getElementById('inspectorCard');\n  const resetInspectorBtn = document.getElementById('resetInspectorBtn');\n  const mediaTypeBadge = document.getElementById('mediaTypeBadge');\n  const mediaIdBadge = document.getElementById('mediaIdBadge');\n\n  const statViews = document.getElementById('statViews');\n  const statLikes = document.getElementById('statLikes');\n  const statComments = document.getElementById('statComments');\n  const statShares = document.getElementById('statShares');\n\n  const mediaVideo = document.getElementById('mediaVideo');\n  const playerTrigger = document.getElementById('playerTrigger');\n  const playOverlay = document.getElementById('playOverlay');\n  const muteBtn = document.getElementById('muteBtn');\n  const timecodeText = document.getElementById('timecodeText');\n  const scrubberFill = document.getElementById('scrubberFill');\n\n  const creatorAvatar = document.getElementById('creatorAvatar');\n  const creatorName = document.getElementById('creatorName');\n  const creatorHandle = document.getElementById('creatorHandle');\n  const durationTag = document.getElementById('durationTag');\n  const mediaCaption = document.getElementById('mediaCaption');\n  const audioTitle = document.getElementById('audioTitle');\n\n  const photoGridWrap = document.getElementById('photoGridWrap');\n  const photoCountLabel = document.getElementById('photoCountLabel');\n  const photoGrid = document.getElementById('photoGrid');\n\n  const btnHdVideo = document.getElementById('btnHdVideo');\n  const videoSubLabel = document.getElementById('videoSubLabel');\n  const btnAudioMp3 = document.getElementById('btnAudioMp3');\n  const btnFastServer = document.getElementById('btnFastServer');\n  const btnCover = document.getElementById('btnCover');\n  const btnCopyLink = document.getElementById('btnCopyLink');\n\n  const recentSection = document.getElementById('recentSection');\n  const recentList = document.getElementById('recentList');\n  const clearHistoryBtn = document.getElementById('clearHistoryBtn');\n  const edgeTelemetryLabel = document.getElementById('edgeTelemetryLabel');\n\n  const THEME_KEY = 'rh_tiktok_studio_theme';\n  const HISTORY_KEY = 'rh_tiktok_user_downloads_v3';\n  const DEMO_LINK = 'https://vt.tiktok.com/ZSgQuVgCe/';\n  let currentCleanUrl = '';\n\n  // 1. Theme Switcher (Default Light Mode, Switchable to Dark Mode)\n  function applyTheme(theme) {\n    const mode = theme === 'dark' ? 'dark' : 'light';\n    htmlRoot.setAttribute('data-theme', mode);\n    if (themeLightBtn && themeDarkBtn) {\n      themeLightBtn.classList.toggle('active', mode === 'light');\n      themeLightBtn.setAttribute('aria-pressed', String(mode === 'light'));\n      themeDarkBtn.classList.toggle('active', mode === 'dark');\n      themeDarkBtn.setAttribute('aria-pressed', String(mode === 'dark'));\n    }\n    try {\n      localStorage.setItem(THEME_KEY, mode);\n    } catch {}\n  }\n\n  try {\n    const savedTheme = localStorage.getItem(THEME_KEY);\n    const initialTheme = savedTheme || htmlRoot.getAttribute('data-theme') || 'light';\n    applyTheme(initialTheme);\n  } catch {\n    applyTheme('light');\n  }\n\n  if (themeLightBtn) {\n    themeLightBtn.addEventListener('click', () => applyTheme('light'));\n  }\n  if (themeDarkBtn) {\n    themeDarkBtn.addEventListener('click', () => applyTheme('dark'));\n  }\n\n  // 2. Clean String & Number Formatting\n  function cleanLabel(str, fallback = 'TikTok Media') {\n    if (!str) return fallback;\n    const stripped = String(str)\n      .replace(/[\\u{1F300}-\\u{1FAFF}\\u{2600}-\\u{27BF}\\u{FE00}-\\u{FE0F}]/gu, '')\n      .replace(/\\s+/g, ' ')\n      .trim();\n    return stripped || fallback;\n  }\n\n  function formatNumber(n) {\n    return Number(n || 0).toLocaleString('en-US');\n  }\n\n  function formatTimecode(sec) {\n    const total = Math.max(0, Math.floor(Number(sec || 0)));\n    const m = Math.floor(total / 60);\n    const s = total % 60;\n    return `${m}:${s < 10 ? '0' : ''}${s}`;\n  }\n\n  // 3. Input Clear & Paste Toggle State\n  function syncInputState() {\n    const hasText = dockUrl.value.trim().length > 0;\n    if (clearInputBtn) {\n      clearInputBtn.style.display = hasText ? 'inline-flex' : 'none';\n    }\n    if (pasteBtn) {\n      pasteBtn.style.display = hasText ? 'none' : 'inline-flex';\n    }\n  }\n\n  dockUrl.addEventListener('input', syncInputState);\n\n  if (clearInputBtn) {\n    clearInputBtn.addEventListener('click', () => {\n      dockUrl.value = '';\n      syncInputState();\n      dockUrl.focus();\n    });\n  }\n\n  if (dismissErrorBtn) {\n    dismissErrorBtn.addEventListener('click', () => {\n      errorBanner.style.display = 'none';\n    });\n  }\n\n  if (resetInspectorBtn) {\n    resetInspectorBtn.addEventListener('click', () => {\n      if (mediaVideo) mediaVideo.pause();\n      inspectorCard.style.display = 'none';\n      dockUrl.value = '';\n      syncInputState();\n      dockUrl.focus();\n    });\n  }\n\n  // 4. Load Live Edge Health Telemetry\n  async function loadEdgeStats() {\n    try {\n      const res = await fetch('/health');\n      if (!res.ok) return;\n      const json = await res.json();\n      if (json?.stats && edgeTelemetryLabel) {\n        const cached = Number(json.stats.cachedVideos || 0);\n        edgeTelemetryLabel.textContent =\n          cached > 0\n            ? `Cloudflare Edge · ${formatNumber(cached)} Cached · 3 Engines`\n            : 'Cloudflare Edge · 3 Engines Active';\n      }\n    } catch {}\n  }\n  loadEdgeStats();\n\n  // 5. User's Own Session History (Only shown when user has downloaded something)\n  function getHistory() {\n    try {\n      const raw = localStorage.getItem(HISTORY_KEY);\n      if (!raw) return [];\n      const parsed = JSON.parse(raw);\n      return Array.isArray(parsed) ? parsed : [];\n    } catch {\n      return [];\n    }\n  }\n\n  function saveToHistory(item) {\n    try {\n      const existing = getHistory().filter((x) => x.id !== item.id);\n      const updated = [item, ...existing].slice(0, 3);\n      localStorage.setItem(HISTORY_KEY, JSON.stringify(updated));\n      renderHistory(updated);\n    } catch {}\n  }\n\n  function renderHistory(items) {\n    if (!recentSection || !recentList) return;\n    if (!Array.isArray(items) || items.length === 0) {\n      recentSection.style.display = 'none';\n      recentList.innerHTML = '';\n      return;\n    }\n\n    recentSection.style.display = 'flex';\n    recentList.innerHTML = '';\n    for (const item of items.slice(0, 3)) {\n      const card = document.createElement('div');\n      card.className = 'recent-item';\n      card.setAttribute('role', 'listitem');\n\n      const img = document.createElement('img');\n      img.className = 'recent-thumb';\n      img.src = item.cover || 'sample-cover.jpg';\n      img.alt = 'Downloaded video thumbnail';\n\n      const info = document.createElement('div');\n      info.className = 'recent-info';\n\n      const title = document.createElement('span');\n      title.className = 'recent-title';\n      title.textContent = cleanLabel(item.title, 'TikTok Video');\n\n      const sub = document.createElement('span');\n      sub.className = 'recent-sub';\n      sub.textContent = `${item.handle || '@tiktok'} · ${formatTimecode(item.duration || 0)}`;\n\n      info.appendChild(title);\n      info.appendChild(sub);\n\n      const loadBtn = document.createElement('button');\n      loadBtn.type = 'button';\n      loadBtn.className = 'btn-recent-load';\n      loadBtn.textContent = 'Open';\n      loadBtn.addEventListener('click', () => {\n        dockUrl.value = item.url || `https://www.tiktok.com/@a/video/${item.id}`;\n        syncInputState();\n        runExtraction(dockUrl.value);\n      });\n\n      card.appendChild(img);\n      card.appendChild(info);\n      card.appendChild(loadBtn);\n      recentList.appendChild(card);\n    }\n  }\n\n  renderHistory(getHistory());\n\n  if (clearHistoryBtn) {\n    clearHistoryBtn.addEventListener('click', () => {\n      try {\n        localStorage.removeItem(HISTORY_KEY);\n      } catch {}\n      renderHistory([]);\n    });\n  }\n\n  // 6. Video Player Transport Controls\n  if (playerTrigger && mediaVideo) {\n    playerTrigger.addEventListener('click', (e) => {\n      if (e.target.closest('#muteBtn')) return;\n      if (mediaVideo.paused) {\n        mediaVideo.play().catch(() => {});\n      } else {\n        mediaVideo.pause();\n      }\n    });\n\n    mediaVideo.addEventListener('play', () => {\n      playOverlay.classList.add('playing');\n    });\n\n    mediaVideo.addEventListener('pause', () => {\n      playOverlay.classList.remove('playing');\n    });\n\n    mediaVideo.addEventListener('ended', () => {\n      playOverlay.classList.remove('playing');\n    });\n\n    mediaVideo.addEventListener('timeupdate', () => {\n      const cur = mediaVideo.currentTime || 0;\n      const dur = mediaVideo.duration || 0;\n      if (timecodeText) {\n        timecodeText.textContent = `${formatTimecode(cur)} / ${formatTimecode(dur)}`;\n      }\n      if (scrubberFill && dur > 0) {\n        const pct = Math.min(100, Math.max(0, (cur / dur) * 100));\n        scrubberFill.style.width = `${pct.toFixed(1)}%`;\n      }\n    });\n  }\n\n  if (muteBtn && mediaVideo) {\n    muteBtn.addEventListener('click', (e) => {\n      e.stopPropagation();\n      mediaVideo.muted = !mediaVideo.muted;\n      muteBtn.style.opacity = mediaVideo.muted ? '0.55' : '1';\n    });\n  }\n\n  // 7. Paste Clipboard & Sample Link Buttons\n  if (pasteBtn) {\n    pasteBtn.addEventListener('click', async () => {\n      try {\n        if (navigator.clipboard && navigator.clipboard.readText) {\n          const text = await navigator.clipboard.readText();\n          if (text && text.trim()) {\n            dockUrl.value = text.trim();\n            syncInputState();\n            if (pasteBtnLabel) pasteBtnLabel.textContent = 'Pasted';\n            setTimeout(() => {\n              if (pasteBtnLabel) pasteBtnLabel.textContent = 'Paste';\n            }, 1200);\n            runExtraction(dockUrl.value);\n          } else {\n            dockUrl.focus();\n          }\n        } else {\n          dockUrl.focus();\n        }\n      } catch {\n        dockUrl.focus();\n      }\n    });\n  }\n\n  if (sampleBtn) {\n    sampleBtn.addEventListener('click', () => {\n      dockUrl.value = DEMO_LINK;\n      syncInputState();\n      runExtraction(DEMO_LINK);\n    });\n  }\n\n  // 8. Copy Clean Link Button\n  if (btnCopyLink) {\n    btnCopyLink.addEventListener('click', async () => {\n      if (!currentCleanUrl) return;\n      try {\n        await navigator.clipboard.writeText(currentCleanUrl);\n        btnCopyLink.textContent = 'Copied Link';\n        setTimeout(() => {\n          btnCopyLink.textContent = 'Copy Clean Link';\n        }, 1200);\n      } catch {}\n    });\n  }\n\n  // 9. Core Extraction Handler\n  async function runExtraction(rawUrl) {\n    const url = (rawUrl || '').trim();\n    if (!url) {\n      dockUrl.focus();\n      return;\n    }\n\n    errorBanner.style.display = 'none';\n    const btnText = extractBtn.querySelector('.btn-text');\n    const btnSpinner = extractBtn.querySelector('.btn-spinner');\n    btnText.style.display = 'none';\n    btnSpinner.style.display = 'inline';\n    extractBtn.disabled = true;\n\n    try {\n      const response = await fetch(`/api/extract?url=${encodeURIComponent(url)}`);\n      const data = await response.json();\n\n      if (!response.ok || !data.success) {\n        throw new Error(data.error || 'Could not resolve TikTok link. Please check that the video is public.');\n      }\n\n      currentCleanUrl = data.id ? `https://www.tiktok.com/@${data.author?.unique_id || 'a'}/video/${data.id}` : url;\n\n      const isPhoto = Array.isArray(data.images) && data.images.length > 0;\n      mediaTypeBadge.textContent = isPhoto ? `Photo Carousel · ${data.images.length} Slides` : 'No Watermark · MP4';\n      mediaIdBadge.textContent = data.id ? `#${String(data.id).slice(0, 8)}` : '#Resolved';\n\n      statViews.textContent = formatNumber(data.stats?.views || 0);\n      statLikes.textContent = formatNumber(data.stats?.likes || 0);\n      statComments.textContent = formatNumber(data.stats?.comments || 0);\n      statShares.textContent = formatNumber(data.stats?.shares || 0);\n\n      creatorAvatar.src = data.author?.avatar || 'sample-avatar.jpg';\n      creatorName.textContent = cleanLabel(data.author?.nickname, 'TikTok Creator');\n      const handleStr = data.author?.unique_id ? `@${data.author.unique_id.replace(/^@/, '')}` : '@tiktok';\n      creatorHandle.textContent = handleStr;\n\n      const durSec = Number(data.duration || 0);\n      const sizeMb = data.sizeBytes ? ` · ${(data.sizeBytes / 1024 / 1024).toFixed(1)} MB` : '';\n      durationTag.textContent = durSec > 0 ? `${durSec}s${sizeMb}` : `HD Stream${sizeMb}`;\n\n      mediaCaption.textContent = cleanLabel(data.title, 'Original TikTok media stream.');\n      audioTitle.textContent = cleanLabel(data.music?.title, 'Original Sound');\n\n      const playableVideo = data.downloads?.fast_video || data.downloads?.hd_video;\n      if (isPhoto) {\n        photoGridWrap.style.display = 'flex';\n        photoCountLabel.textContent = `${data.images.length} slides`;\n        photoGrid.innerHTML = '';\n        data.images.slice(0, 6).forEach((imgUrl, idx) => {\n          const a = document.createElement('a');\n          a.className = 'photo-slide';\n          a.href = `/api/download?url=${encodeURIComponent(imgUrl)}&filename=tiktok_${data.id || Date.now()}_slide_${idx + 1}.jpg`;\n          a.setAttribute('download', '');\n          const im = document.createElement('img');\n          im.src = imgUrl;\n          im.alt = `Carousel slide ${idx + 1}`;\n          a.appendChild(im);\n          photoGrid.appendChild(a);\n        });\n      } else {\n        photoGridWrap.style.display = 'none';\n      }\n\n      if (playableVideo) {\n        mediaVideo.src = `/api/download?url=${encodeURIComponent(playableVideo)}&inline=1`;\n        mediaVideo.poster = data.cover || '';\n        mediaVideo.load();\n        timecodeText.textContent = `0:00 / ${formatTimecode(durSec)}`;\n        scrubberFill.style.width = '0%';\n      }\n\n      const videoFilename = `tiktok_${data.id || Date.now()}_clean.mp4`;\n      const audioFilename = `tiktok_${data.id || Date.now()}_audio.mp3`;\n\n      if (data.downloads?.hd_video || data.downloads?.fast_video) {\n        const targetVid = data.downloads.hd_video || data.downloads.fast_video;\n        const fallbackVid = data.downloads.fast_video || '';\n        btnHdVideo.href = `/api/download?url=${encodeURIComponent(targetVid)}&fallback=${encodeURIComponent(fallbackVid)}&filename=${encodeURIComponent(videoFilename)}`;\n        btnHdVideo.style.display = 'flex';\n        videoSubLabel.textContent = `Original MP4 · H.264 Stream${sizeMb}`;\n      } else {\n        btnHdVideo.style.display = 'none';\n      }\n\n      if (data.downloads?.audio) {\n        btnAudioMp3.href = `/api/download?url=${encodeURIComponent(data.downloads.audio)}&filename=${encodeURIComponent(audioFilename)}`;\n        btnAudioMp3.style.display = 'flex';\n      } else {\n        btnAudioMp3.style.display = 'none';\n      }\n\n      if (data.downloads?.fast_video) {\n        btnFastServer.href = `/api/download?url=${encodeURIComponent(data.downloads.fast_video)}&filename=${encodeURIComponent(videoFilename)}`;\n        btnFastServer.style.display = 'inline-flex';\n      }\n\n      if (data.cover) {\n        btnCover.href = data.cover;\n      }\n\n      inspectorCard.style.display = 'flex';\n      inspectorCard.scrollIntoView({ behavior: 'smooth', block: 'start' });\n\n      saveToHistory({\n        id: String(data.id || Date.now()),\n        url,\n        title: cleanLabel(data.title, 'TikTok Video'),\n        handle: handleStr,\n        duration: durSec || 15,\n        cover: data.cover || ''\n      });\n\n      loadEdgeStats();\n    } catch (err) {\n      errorText.textContent = err.message || 'Could not resolve TikTok link. Please check that the video is public.';\n      errorBanner.style.display = 'flex';\n    } finally {\n      btnText.style.display = 'inline';\n      btnSpinner.style.display = 'none';\n      extractBtn.disabled = false;\n    }\n  }\n\n  extractForm.addEventListener('submit', (e) => {\n    e.preventDefault();\n    runExtraction(dockUrl.value);\n  });\n\n  syncInputState();\n});\n";
